import{_ as n,a0 as p,w as o,s as r,I as i,x as e,a1 as t,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"管理你的 shell 环境 | LCTT x X-CMD","titleTemplate":false,"description":"管理你的 shell 环境 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理你的 shell 环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理你的 shell 环境 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190705 Manage your shell environment","title":"管理你的 shell 环境","tag":"201907","desc":""},"relativePath":"201907/20190705 Manage your shell environment.md","filePath":"[post].md"}'),h={name:"201907/20190705 Manage your shell environment.md"};function g(u,s,b,k,c,f){const a=p("Link");return o(),r("div",null,[s[18]||(s[18]=i("h1",{id:"管理你的-shell-环境",tabindex:"-1"},[e("管理你的 shell 环境 "),i("a",{class:"header-anchor",href:"#管理你的-shell-环境","aria-label":"Permalink to “管理你的 shell 环境”"},"​")],-1)),s[19]||(s[19]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/05/manage-shell-env-816x345.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("前段时间，Fedora Magazine 发表了一篇 ",-1)),t(a,{href:"https://fedoramagazine.org/set-zsh-fedora-system/"},{default:l(()=>[...s[0]||(s[0]=[e("介绍 ZSH",-1)])]),_:1}),s[2]||(s[2]=e(" 的文章，它是 Fedora 默认的 bash shell 的替代品。这一次，我们将着重定制它来更有效地使用它。本文中显示的所有概念也适用于其他 shell，例如 bash。",-1))]),s[20]||(s[20]=d(`<h3 id="别名" tabindex="-1">别名 <a class="header-anchor" href="#别名" aria-label="Permalink to “别名”">​</a></h3><p>别名是命令的快捷方式。为那些需要经常执行，但需要很长时间输入的长命令创建快捷方式很有用。语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias yourAlias=&#39;complex command with arguments&#39;</span></span></code></pre></div><p>它们并不总是用来缩短长命令。重要的是，你将它们用于你经常执行的任务。可能的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias dnfUpgrade=&#39;dnf -y upgrade&#39;</span></span></code></pre></div><p>这样，为了进行系统升级，我只需输入 <code>dnfUpgrade</code> 而不用输入完整的 <code>dnf</code> 命令。</p><p>在终端中设置别名的问题是，一旦终端会话关闭，别名就会丢失。要永久设置它们，请使用资源文件。</p><h3 id="资源文件" tabindex="-1">资源文件 <a class="header-anchor" href="#资源文件" aria-label="Permalink to “资源文件”">​</a></h3><p>资源文件（即 rc 文件）是在会话或进程开始时（每个用户在开启新终端窗口或启动 vim 等新程序时）加载的配置文件。对于 ZSH，资源文件是 <code>.zshrc</code>，对于 bash，它是 <code>.bashrc</code>。</p><p>要使别名成为永久别名，你可以将它们放入资源文件中。你可以使用你选择的文本编辑器编辑资源文件。这里使用 vim：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $HOME/.zshrc</span></span></code></pre></div><p>或者对于 bash：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $HOME/.bashrc</span></span></code></pre></div><p>请注意，资源文件的位置是相对于家目录指定的。这是 ZSH（或 bash）默认为每个用户查找该文件的位置。</p><p>还有一种是将你的配置放在任何其他文件中，然后读取它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source /path/to/your/rc/file</span></span></code></pre></div><p>同样，在会话中直接读取它只会将其应用于会话，因此要使其永久化，请将 <code>source</code> 命令添加到资源文件中。将文件放在不同位置的优点是你可以随时读取它。这在共享环境中很有用。</p><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to “环境变量”">​</a></h3><p>环境变量是分配了特定名称的值，你可以在脚本和命令中调用它们。它们以美元符号（<code>$</code>）开始。其中最常见的是指向主目录的 <code>$HOME</code>。</p><p>顾名思义，环境变量是你环境的一部分。使用以下语法设置变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ http_proxy=&quot;http://your.proxy&quot;</span></span></code></pre></div><p>要使其成为环境变量，请使用以下命令将其导出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export $http_proxy</span></span></code></pre></div><p>要查看当前设置的所有环境变量，请使用 <code>env</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env</span></span></code></pre></div><p>该命令输出会话中可用的所有变量。要演示如何在命令中使用它们，请尝试运行以下 <code>echo</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PWD</span></span>
<span class="line"><span>/home/fedora</span></span>
<span class="line"><span>$ echo $USER</span></span>
<span class="line"><span>fedora</span></span></code></pre></div><p>这里发生了变量扩展，即存储在变量中的值在命令中使用。</p><p>另一个有用的变量是 <code>$PATH</code>，它定义了 shell 查找二进制文件的目录。</p><h3 id="path-变量" tabindex="-1">$PATH 变量 <a class="header-anchor" href="#path-变量" aria-label="Permalink to “$PATH 变量”">​</a></h3><p>有许多对于操作系统很重要的目录或文件夹（在图形环境中调用它们的方式）。某些目录设置为保存可直接在 shell 中使用的二进制文件。这些目录在 <code>$PATH</code> 变量中定义。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/lib64/qt-3.3/bin:/usr/share/Modules/bin:/usr/lib64/ccache:/usr/local/bin:/usr/bin:/bin:/usr/local/sbin:/usr/sbin:/usr/libexec/sdcc:/usr/libexec/sdcc:/usr/bin:/bin:/sbin:/usr/sbin:/opt/FortiClient</span></span></code></pre></div><p>当你希望在 shell 中访问自己的二进制文件（或脚本）时，这会有帮助。</p><hr>`,34)),i("p",null,[s[4]||(s[4]=e("via: ",-1)),t(a,{href:"https://fedoramagazine.org/manage-your-shell-environment/"},{default:l(()=>[...s[3]||(s[3]=[e("https://fedoramagazine.org/manage-your-shell-environment/",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=e("作者：",-1)),t(a,{href:"https://fedoramagazine.org/author/x3mboy/"},{default:l(()=>[...s[5]||(s[5]=[e("Eduard Lucena",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:l(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const x=n(h,[["render",g]]);export{v as __pageData,x as default};
